s=s[:a]+'''   <section className={card}><div className="flex items-center justify-between"><h3 className="font-semibold">Store Table Management</h3><button className={button} onClick={()=>{setStoreDraft({index:null,retailerKey:config.key,key:'',name:'',address:'',status:'Active',exception:false});setView('store');}}><Plus size={16}/>Add Store</button></div><div className="overflow-x-auto"><table className="w-full text-sm text-left"><thead className="text-slate-400"><tr>{['Retailer Store ID','Retailer Store Name','SUITE Storecode','Active','Inactive','Edit'].map(h=><th key={h} className="p-3 whitespace-nowrap">{h}</th>)}</tr></thead><tbody>{config.stores.map((store,i)=><tr key={store.id||i} className="border-t border-slate-700"><td className="p-3">{store.key}</td><td className="p-3">{store.name}</td><td className="p-3 font-mono text-xs">{store.suiteCode||'Generated on save'}</td><td className="p-3"><span aria-label={`${store.key} active: ${(store.status||'Active')==='Active'?'yes':'no'}`} className="text-emerald-300">{(store.status||'Active')==='Active'?'●':''}</span></td><td className="p-3"><span aria-label={`${store.key} inactive: ${store.status==='Inactive'?'yes':'no'}`} className="text-slate-400">{store.status==='Inactive'?'●':''}</span></td><td className="p-3"><button className={button} title="Edit store" aria-label={`Edit store ${store.key}`} onClick={()=>{setStoreDraft({status:'Active',exception:false,address:'',...store,index:i,retailerKey:config.key});setView('store');}}><Pencil size={16}/></button></td></tr>)}</tbody></table>{!config.stores.length&&<p className="text-sm text-slate-400 py-4">No stores yet. Add a retailer store.</p>}</div></section>
'''+s[b:]
loc=s.index("  {view==='rules'&&<section")
s=s[:loc]+'''  {view==='store'&&storeDraft&&<section className={card} aria-label="Store edit page"><div className="flex justify-between gap-3"><h2 className="text-xl font-semibold">{storeDraft.index===null?'Add Store':'Edit Store'}</h2><button className={button} disabled={busy} onClick={()=>{setStoreDraft(null);setView('setup');}}>Back to Store Table</button></div><div className="grid grid-cols-1 md:grid-cols-2 gap-5"><Field label="Retailer Name"><input className={input} readOnly value={config.name}/></Field><fieldset className="space-y-3"><legend className="text-sm text-slate-300">Status</legend><div className="flex gap-5">{['Active','Inactive'].map(status=><label key={status} className="flex items-center gap-2 text-sm"><input type="radio" name="store-status" value={status} checked={storeDraft.status===status} onChange={()=>setStoreDraft(d=>({...d,status}))}/>{status}</label>)}</div></fieldset><Field label="Retailer Key"><input className={input} maxLength={64} value={storeDraft.retailerKey} onChange={e=>setStoreDraft(d=>({...d,retailerKey:e.target.value}))}/><span className="text-xs text-slate-400">Shared retailer key: saving updates it for all this retailer's stores.</span></Field><fieldset className="space-y-3"><legend className="text-sm text-slate-300">Exception status</legend><div className="flex gap-5">{[{label:'Yes',value:true},{label:'No',value:false}].map(option=><label key={option.label} className="flex items-center gap-2 text-sm"><input type="radio" name="store-exception" checked={storeDraft.exception===option.value} onChange={()=>setStoreDraft(d=>({...d,exception:option.value}))}/>{option.label}</label>)}</div></fieldset><Field label="Store ID"><input className={input} maxLength={64} value={storeDraft.key} onChange={e=>setStoreDraft(d=>({...d,key:e.target.value}))}/></Field><Field label="SUITE Storecode"><input className={input} readOnly value={storeDraft.suiteCode||''} placeholder="Autogenerated once saved"/></Field><Field label="Store Name"><input className={input} maxLength={120} value={storeDraft.name} onChange={e=>setStoreDraft(d=>({...d,name:e.target.value}))}/></Field><Field label="Store Address"><textarea className={input} rows={3} maxLength={2000} value={storeDraft.address} onChange={e=>setStoreDraft(d=>({...d,address:e.target.value}))}/></Field></div><div className="flex justify-end gap-3"><button className={primary} disabled={busy||!storeDraft.key.trim()||!storeDraft.name.trim()||!storeDraft.retailerKey.trim()} onClick={async()=>{const {index,retailerKey,...store}=storeDraft;const stores=index===null?[...config.stores,store]:config.stores.map((s,i)=>i===index?store:s);const result=await save({...config,key:retailerKey,stores});if(result){setStoreDraft(null);setView('setup');setNotice('Store saved. SUITE storecode assigned and retailer key updated.');}}}>Save Store</button><button className={button} disabled={busy} onClick={()=>{setStoreDraft(null);setView('setup');}}>Cancel</button></div></section>}
'''+s[loc:]
